import boto3, json, os, time, uuid
s3 = boto3.client('s3')
def invoke(event, context):
    body = json.loads(event.get('body') or '{}')
    path = event['rawPath'].strip('/')
    status = 503 if path == 'control' else int(path)
    if body.get('Type') == 'SubscriptionConfirmation' and path != 'control': status = 200
    response = {'statusCode': status, 'body': 'observed status ' + str(status)}
    if not body.get('_probe'):
        record = {'received_at': time.time(), 'path': path, 'message': body, 'response': response}
        s3.put_object(Bucket=os.environ['BUCKET'], Key=str(time.time_ns()) + '-' + str(uuid.uuid4()) + '.json', Body=json.dumps(record).encode())
    return response

